use rusqlite::{params,Connection};use serde::Serialize;use std::{path::Path,sync::{Arc,Mutex}};use uuid::Uuid;use crate::CreateTask;
#[derive(Clone)]pub struct Store(Arc<Mutex<Connection>>);
#[derive(Clone,Serialize)]pub struct TaskRecord{pub id:String,pub title:String,pub description:String,pub department:String,pub priority:String,pub status:String,pub approval_required:bool,pub created_at:i64,pub updated_at:i64}
impl Store{
pub fn open(path:impl AsRef<Path>)->Result<Self,String>{let c=Connection::open(path).map_err(|e|e.to_string())?;c.execute_batch("PRAGMA journal_mode=WAL;PRAGMA busy_timeout=5000;CREATE TABLE IF NOT EXISTS tasks(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,department TEXT NOT NULL,priority TEXT NOT NULL,status TEXT NOT NULL,approval_required INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);CREATE INDEX IF NOT EXISTS tasks_created_at ON tasks(created_at DESC);").map_err(|e|e.to_string())?;Ok(Self(Arc::new(Mutex::new(c))))}
pub fn list_tasks(&self)->Result<Vec<TaskRecord>,String>{let c=self.0.lock().map_err(|_|"Database lock poisoned".to_string())?;let mut q=c.prepare("SELECT id,title,description,department,priority,status,approval_required,created_at,updated_at FROM tasks ORDER BY created_at DESC LIMIT 200").map_err(|e|e.to_string())?;let rows=q.query_map([],|r|Ok(TaskRecord{id:r.get(0)?,title:r.get(1)?,description:r.get(2)?,department:r.get(3)?,priority:r.get(4)?,status:r.get(5)?,approval_required:r.get::<_,i64>(6)?==1,created_at:r.get(7)?,updated_at:r.get(8)?})).map_err(|e|e.to_string())?;rows.map(|r|r.map_err(|e|e.to_string())).collect()}
pub fn create_task(&self,x:&CreateTask)->Result<TaskRecord,String>{let n=now_ms();let t=TaskRecord{id:Uuid::new_v4().to_string(),title:x.title.trim().into(),description:x.description.trim().into(),department:x.department.clone(),priority:x.priority.clone(),status:"awaiting_approval".into(),approval_required:true,created_at:n,updated_at:n};let c=self.0.lock().map_err(|_|"Database lock poisoned".to_string())?;c.execute("INSERT INTO tasks(id,title,description,department,priority,status,approval_required,created_at,updated_at) VALUES(?1,?2,?3,?4,?5,?6,1,?7,?7)",params![t.id,t.title,t.description,t.department,t.priority,t.status,n]).map_err(|e|e.to_string())?;Ok(t)}
pub fn approve_task(&self,id:&str)->Result<TaskRecord,String>{let c=self.0.lock().map_err(|_|"Database lock poisoned".to_string())?;let n=c.execute("UPDATE tasks SET status='queued',approval_required=0,updated_at=?1 WHERE id=?2 AND status='awaiting_approval'",params![now_ms(),id]).map_err(|e|e.to_string())?;if n!=1{return Err("Task does not exist or is not awaiting approval.".into())}let mut q=c.prepare("SELECT id,title,description,department,priority,status,approval_required,created_at,updated_at FROM tasks WHERE id=?1").map_err(|e|e.to_string())?;q.query_row([id],|r|Ok(TaskRecord{id:r.get(0)?,title:r.get(1)?,description:r.get(2)?,department:r.get(3)?,priority:r.get(4)?,status:r.get(5)?,approval_required:r.get::<_,i64>(6)?==1,created_at:r.get(7)?,updated_at:r.get(8)?})).map_err(|e|e.to_string())}
pub fn cancel_task(&self,id:&str)->Result<TaskRecord,String>{let c=self.0.lock().map_err(|_|"Database lock poisoned".to_string())?;let n=c.execute("UPDATE tasks SET status='cancelled',approval_required=0,updated_at=?1 WHERE id=?2 AND status IN ('awaiting_approval','queued')",params![now_ms(),id]).map_err(|e|e.to_string())?;if n!=1{return Err("Task does not exist or can no longer be cancelled.".into())}let mut q=c.prepare("SELECT id,title,description,department,priority,status,approval_required,created_at,updated_at FROM tasks WHERE id=?1").map_err(|e|e.to_string())?;q.query_row([id],|r|Ok(TaskRecord{id:r.get(0)?,title:r.get(1)?,description:r.get(2)?,department:r.get(3)?,priority:r.get(4)?,status:r.get(5)?,approval_required:r.get::<_,i64>(6)?==1,created_at:r.get(7)?,updated_at:r.get(8)?})).map_err(|e|e.to_string())}
}
fn now_ms()->i64{std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis() as i64}
#[cfg(test)]mod tests{use super::*;#[test]fn task_requires_approval_and_persists(){let p=std::env::temp_dir().join(format!("kevin-office-{}.db",Uuid::new_v4()));let s=Store::open(&p).unwrap();let x=CreateTask{title:"Prepare release notes".into(),description:"Summarize tested changes".into(),department:"development".into(),priority:"normal".into()};let t=s.create_task(&x).unwrap();assert_eq!(t.status,"awaiting_approval");assert!(t.approval_required);let a=s.approve_task(&t.id).unwrap();assert_eq!(a.status,"queued");assert!(!a.approval_required);assert_eq!(s.list_tasks().unwrap().len(),1);drop(s);let _=std::fs::remove_file(p);}
#[test]fn cancellation_is_terminal_and_only_allowed_before_execution(){let p=std::env::temp_dir().join(format!("kevin-office-cancel-{}.db",Uuid::new_v4()));let s=Store::open(&p).unwrap();let x=CreateTask{title:"Cancel safely".into(),description:String::new(),department:"management".into(),priority:"normal".into()};let t=s.create_task(&x).unwrap();let c=s.cancel_task(&t.id).unwrap();assert_eq!(c.status,"cancelled");assert!(!c.approval_required);assert!(s.cancel_task(&t.id).is_err());drop(s);let _=std::fs::remove_file(p);}}